        "kernel_unified_attention_2d": "@triton.jit\ndef kernel_unified_attention_2d(\n    output_ptr,  # [num_tokens, num_query_heads, head_size]\n    query_ptr,  # [num_tokens, num_query_heads, head_size]\n    key_cache_ptr,  # [num_blks, num_kv_heads, head_size // x, blk_size, x]\n    value_cache_ptr,  # [num_blks, num_kv_heads, head_size, blk_size]\n    block_tables_ptr,  # [num_seqs, max_num_blocks_per_seq]\n    seq_lens_ptr,  # [num_seqs]\n    alibi_slopes_ptr,  # [num_query_heads]\n    scale,  # float32\n    k_scale,  # float32\n    v_scale,  # float32\n    softcap,  # float32\n    num_query_heads: tl.constexpr,  # int\n    num_queries_per_kv: tl.constexpr,  # int\n    block_table_stride: tl.int64,  # int\n    query_stride_0: tl.int64,  # int\n    query_stride_1: tl.int64,  # int, should be equal to head_size\n    output_stride_0: tl.int64,  # int\n    output_stride_1: tl.int64,  # int, should be equal to head_size\n    BLOCK_SIZE: tl.constexpr,  # int\n    HEAD_SIZE: tl.constexpr,  # int\n    HEAD_SIZE_PADDED: tl.constexpr,  # int, must be power of 2\n    USE_ALIBI_SLOPES: tl.constexpr,  # bool\n    USE_SOFTCAP: tl.constexpr,  # bool\n    SLIDING_WINDOW: tl.constexpr,  # int\n    stride_k_cache_0: tl.int64,  # int\n    stride_k_cache_1: tl.int64,  # int\n    stride_k_cache_2: tl.int64,  # int\n    stride_k_cache_3: tl.int64,  # int\n    stride_v_cache_0: tl.int64,  # int\n    stride_v_cache_1: tl.int64,  # int\n    stride_v_cache_2: tl.int64,  # int\n    stride_v_cache_3: tl.int64,  # int\n    query_start_len_ptr,  # [num_seqs+1]\n    BLOCK_Q: tl.constexpr,  # int\n    num_seqs: tl.int32,\n):\n    # Program ID: seq_idx * kv_head_idx * query_block\n    seq_idx = tl.program_id(0)\n    kv_head_idx = tl.program_id(1)\n    query_block_idx = tl.program_id(2)\n    \n    # Get sequence information\n    seq_start = tl.load(query_start_len_ptr + seq_idx)\n    seq_end = tl.load(query_start_len_ptr + seq_idx + 1)\n    query_len = seq_end - seq_start\n    kv_len = tl.load(seq_lens_ptr + seq_idx)\n    \n    # Calculate query block range\n    query_start = query_block_idx * BLOCK_Q\n    query_end = tl.minimum(query_start + BLOCK_Q, query_len)\n    \n    # If this query block is empty, return\n    if query_start >= query_end:\n        return\n    \n    # Calculate query head indices for this KV head\n    query_head_start = kv_head_idx * num_queries_per_kv\n    query_head_end = tl.minimum(query_head_start + num_queries_per_kv, num_query_heads)\n    num_heads_this_kv = query_head_end - query_head_start\n    \n    # Create masks\n    head_mask = tl.arange(0, num_queries_per_kv) < num_heads_this_kv\n    dim_mask = tl.arange(0, HEAD_SIZE_PADDED) < HEAD_SIZE\n    \n    # Initialize accumulators for streaming softmax\n    m_i = tl.full([BLOCK_Q, num_queries_per_kv], float(\"-inf\"), dtype=tl.float32)\n    l_i = tl.full([BLOCK_Q, num_queries_per_kv], 0.0, dtype=tl.float32)\n    acc = tl.zeros([BLOCK_Q, num_queries_per_kv, HEAD_SIZE_PADDED], dtype=tl.float32)\n    \n    # Load query block\n    Q = tl.zeros([BLOCK_Q, num_queries_per_kv, HEAD_SIZE_PADDED], dtype=tl.float32)\n    \n    # Load all queries for this block\n    offs_qm = tl.arange(0, BLOCK_Q)\n    offs_qh = tl.arange(0, num_queries_per_kv)\n    offs_qd = tl.arange(0, HEAD_SIZE_PADDED)\n    \n    # Calculate query offsets\n    qm = query_start + offs_qm[:, None, None]\n    qh = query_head_start + offs_qh[None, :, None]\n    \n    # Mask for valid queries\n    q_mask = (qm < query_end) & (qh < query_head_end) & head_mask[None, :, None] & dim_mask[None, None, :]\n    \n    # Calculate query pointer offsets\n    query_offset = (seq_start * query_stride_0 + \n                   qm * query_stride_0 + \n                   qh * query_stride_1 + \n                   offs_qd[None, None, :])\n    \n    # Load queries\n    Q = tl.load(query_ptr + query_offset, mask=q_mask, other=0.0)\n    \n    # Scale queries\n    Q = Q * scale\n    \n    # Get block table for this sequence\n    block_table_offset = seq_idx * block_table_stride\n    num_blocks = cdiv_fn(kv_len, BLOCK_SIZE)\n    \n    # Iterate over KV blocks\n    for block_idx in range(num_blocks):\n        physical_block_idx = tl.load(block_tables_ptr + block_table_offset + block_idx)\n        \n        # Calculate offsets within this block\n        block_start = block_idx * BLOCK_SIZE\n        block_end = tl.minimum(block_start + BLOCK_SIZE, kv_len)\n        block_len = block_end - block_start\n        \n        # Load key block\n        offs_n = tl.arange(0, BLOCK_SIZE)\n        offs_d = tl.arange(0, HEAD_SIZE_PADDED)\n        \n        # Calculate key offsets - note: x is stride_k_cache_3\n        k_offset = (physical_block_idx * stride_k_cache_0 +\n                   kv_head_idx * stride_k_cache_1 +\n                   (offs_d[:, None] // stride_k_cache_3) * stride_k_cache_2 +\n                   offs_n[None, :] * stride_k_cache_3 +\n                   (offs_d[:, None] % stride_k_cache_3))\n        \n        # Mask for valid keys\n        k_mask = dim_mask[:, None] & (offs_n[None, :] < block_len)\n        \n        K_load = tl.load(key_cache_ptr + k_offset, mask=k_mask, other=0.0)\n        \n        # Apply K scale if needed\n        if K_load.dtype.is_fp8():\n            # Load scale for this sequence and KV head\n            scale_idx = seq_idx * num_queries_per_kv + kv_head_idx\n            K = (K_load.to(tl.float32) * tl.load(k_scale + scale_idx)).to(Q.dtype)\n        else:\n            K = K_load\n        \n        # Compute attention scores\n        S = tl.dot(Q, K)\n        \n        # Apply causal masking\n        # For causal attention, query at position q can only attend to keys at positions k <= q + (kv_len - query_len)\n        kv_positions = block_start + offs_n[None, None, :]\n        query_positions = query_start + offs_qm[:, None, None]\n        \n        # Calculate the offset for causal masking\n        causal_offset = kv_len - query_len\n        can_attend = kv_positions <= (query_positions + causal_offset)\n        \n        # Apply causal mask\n        S = tl.where(can_attend, S, float(\"-inf\"))\n        \n        # Apply sliding window if specified\n        if SLIDING_WINDOW > 0:\n            # Query can only attend to KV within sliding window\n            window_mask = (kv_len - kv_positions) < (SLIDING_WINDOW + query_positions)\n            S = tl.where(window_mask, S, -10000.0)\n        \n        # Apply ALiBi slopes if enabled\n        if USE_ALIBI_SLOPES:\n            # Load alibi slopes for all query heads\n            alibi_slopes = tl.load(alibi_slopes_ptr + query_head_start + offs_qh, \n                                  mask=head_mask, other=0.0)\n            \n            # ALiBi bias: -slope * |position difference|\n            # position_diff = kv_position - (query_position + causal_offset)\n            position_diff = kv_positions - (query_positions + causal_offset)\n            alibi_bias = -alibi_slopes[None, :, None] * tl.abs(position_diff)\n            S = S + alibi_bias\n        \n        # Apply softcap if enabled\n        if USE_SOFTCAP and softcap > 0:\n            S = apply_softcap(softcap, S)\n        \n        # Load value block\n        v_offset = (physical_block_idx * stride_v_cache_0 +\n                   kv_head_idx * stride_v_cache_1 +\n                   offs_d[None, :] * stride_v_cache_2 +\n                   offs_n[:, None] * stride_v_cache_3)\n        \n        # Mask for valid values\n        v_mask = dim_mask[None, :] & (offs_n[:, None] < block_len)\n        \n        V_load = tl.load(value_cache_ptr + v_offset, mask=v_mask, other=0.0)\n        \n        # Apply V scale if needed\n        if V_load.dtype.is_fp8():\n            # Load scale for this sequence and KV head\n            scale_idx = seq_idx * num_queries_per_kv + kv_head_idx\n            V = (V_load.to(tl.float32) * tl.load(v_scale + scale_idx)).to(Q.dtype)\n        else:\n            V = V_load\n        \n        # Streaming softmax update\n        # Find max for each query position and head\n        m_ij = tl.maximum(m_i, tl.max(S, axis=2))\n        \n        # Compute softmax numerator\n        p = tl.exp(S - m_ij[:, :, None])\n        \n        # Compute sum for normalization\n        l_ij = tl.sum(p, axis=2)\n        \n        # Update accumulators\n        alpha = tl.exp(m_i - m_ij)\n        acc = acc * alpha[:, :, None]\n        acc += tl.dot(p, V)\n        \n        # Update running statistics\n        l_i = l_i * alpha + l_ij\n        m_i = m_ij\n    \n    # Final normalization\n    acc = acc / l_i[:, :, None]\n    \n    # Store results\n    # Calculate output offsets\n    om = seq_start + query_start + offs_qm[:, None, None]\n    oh = query_head_start + offs_qh[None, :, None]\n    \n    # Mask for valid outputs\n    out_mask = (om < seq_end) & (oh < query_head_end) & head_mask[None, :, None] & dim_mask[None, None, :]\n    \n    # Calculate output pointer offsets\n    output_offset = (om * output_stride_0 + \n                    oh * output_stride_1 + \n                    offs_qd[None, None, :])\n    \n    # Store outputs\n    tl.store(output_ptr + output_offset, acc, mask=out_mask)",
        "unified_attention": "def unified_attention(\n    q,\n    k,\n    v,\n    out,\n    cu_seqlens_q,\n    max_seqlen_q,\n    seqused_k,\n    max_seqlen_k,\n    softmax_scale,\n    causal,\n    window_size,\n    block_table,\n    softcap,\n    q_descale,\n    k_descale,\n    v_descale,\n    alibi_slopes=None,\n):\n    # Validate inputs\n    assert causal, \"Only causal attention is supported\"\n    assert q.dim() == 3, \"Query must be 3D [num_tokens, num_heads, head_size]\"\n    assert k.dim() == 5, \"Key cache must be 5D [num_blocks, num_kv_heads, head_size//x, block_size, x]\"\n    assert v.dim() == 4, \"Value cache must be 4D [num_blocks, num_kv_heads, head_size, block_size]\"\n    \n    # Get dimensions\n    num_tokens = q.shape[0]\n    num_query_heads = q.shape[1]\n    head_size = q.shape[2]\n    \n    num_seqs = cu_seqlens_q.shape[0] - 1\n    num_kv_heads = k.shape[1]\n    block_size = v.shape[3]  # v shape: [num_blocks, num_kv_heads, head_size, block_size]\n    \n    # Validate GQA\n    assert num_query_heads % num_kv_heads == 0, \"num_query_heads must be divisible by num_kv_heads\"\n    num_queries_per_kv = num_query_heads // num_kv_heads\n    \n    # Get window size\n    if window_size is not None and len(window_size) == 2:\n        sliding_window = window_size[0] + 1 if window_size[0] >= 0 else 0\n    else:\n        sliding_window = 0\n    \n    # Prepare alibi slopes\n    use_alibi_slopes = alibi_slopes is not None\n    if alibi_slopes is None:\n        alibi_slopes = torch.empty(0, device=q.device, dtype=torch.float32)\n    \n    # Prepare scales\n    if k_descale is None:\n        k_descale = torch.tensor(1.0, device=q.device, dtype=torch.float32)\n    if v_descale is None:\n        v_descale = torch.tensor(1.0, device=q.device, dtype=torch.float32)\n    \n    # Convert query_start_len_ptr from cu_seqlens_q\n    query_start_len_ptr = cu_seqlens_q\n    \n    # Determine block size for queries\n    BLOCK_Q = 1  # Start with 1 for simplicity, could be tuned\n    \n    # Calculate grid size\n    grid = (num_seqs, num_kv_heads, triton.cdiv(max_seqlen_q, BLOCK_Q))\n    \n    # Get padded head size\n    HEAD_SIZE_PADDED = triton.next_power_of_2(head_size)\n    \n    # Launch kernel\n    kernel_unified_attention_2d[grid](\n        output_ptr=out,\n        query_ptr=q,\n        key_cache_ptr=k,\n        value_cache_ptr=v,\n        block_tables_ptr=block_table,\n        seq_lens_ptr=seqused_k,\n        alibi_slopes_ptr=alibi_slopes,\n        scale=softmax_scale,\n        k_scale=k_descale,\n        v_scale=v_descale,\n        softcap=softcap if softcap is not None else 0.0,\n        num_query_heads=num_query_heads,\n        num_queries_per_kv=num_queries_per_kv,\n        block_table_stride=block_table.stride(0),\n        query_stride_0=q.stride(0),\n        query_stride_1=q.stride(1),\n        output_stride_0=out.stride(0),\n        output_stride_1=out.stride(1),\n        BLOCK_SIZE=block_size,\n        HEAD_SIZE=head_size,\n        HEAD_SIZE_PADDED=HEAD_SIZE_PADDED,\n        USE_ALIBI_SLOPES=use_alibi_slopes,\n        USE_SOFTCAP=softcap is not None and softcap > 0,\n        SLIDING_WINDOW=sliding_window,\n        stride_k_cache_0=k.stride(0),\n        stride_k_cache_1=k.stride(1),\n        stride_k_cache_2=k.stride(2),\n        stride_k_cache_3=k.stride(3),\n        stride_v_cache_0=v.stride(0),\n        stride_v_cache_1=v.stride(1),\n        stride_v_cache_2=v.stride(2),\n        stride_v_cache_3=v.stride(3),\n        query_start_len_ptr=query_start_len_ptr,\n        BLOCK_Q=BLOCK_Q,\n        num_seqs=num_seqs,\n        num_warps=8,\n        num_stages=3,\n    )"
    }
}
EOF"}

